export fn scaled_exponential_linear_unit(v:[*c]const i64,n:usize,out:[*c]u8,cap:usize)i64{
 if(v==null or n<3 or n>259)return -1;if(v[0]<0 or v[0]>256 or n!=@as(usize,@intCast(v[0]))+3 or v[1]<-10000000 or v[1]>10000000 or v[2]<-10000000 or v[2]>10000000)return -1;const count:usize=@intCast(v[0]);for(0..count)|i|if(v[i+3]<-20000000 or v[i+3]>20000000)return -1;const bytes=count*8;if(out==null or cap<bytes)return -2;const alpha=@as(f64,@floatFromInt(v[1]))/1e6;const lambda=@as(f64,@floatFromInt(v[2]))/1e6;for(0..count)|i|{const x=@as(f64,@floatFromInt(v[i+3]))/1e6;const inner=if(x>0.0)x else alpha*(@exp(x)-1.0);const y=lambda*inner;const q:i64=@intFromFloat(@floor(y*1e9+0.5));const bits=@as(u64,@bitCast(q));for(0..8)|b|out[i*8+b]=@truncate(bits>>(8*b));}return @intCast(bytes);
}
